package com.lolfm.composition;
import com.lolfm.champion.ChampionRoleKey;import java.util.*;
public final class CompositionPatternEvaluator{public Map<CompositionPattern,PatternEvaluation>evaluate(TeamCompositionCoverage coverage){EnumMap<CompositionPattern,PatternEvaluation>out=new EnumMap<>(CompositionPattern.class);CompositionPatternPolicy.definitions().forEach((p,d)->out.put(p,evaluate(d,coverage)));return Map.copyOf(out);}public PatternEvaluation evaluate(PatternDefinition d,TeamCompositionCoverage coverage){EnumMap<CompositionCapability,Double>components=new EnumMap<>(CompositionCapability.class);List<ChampionRoleKey>primary=new ArrayList<>(),supporting=new ArrayList<>();double product=1;for(var c:d.components()){var cc=coverage.capability(c);components.put(c,cc.coverage());product*=cc.coverage();primary.add(cc.contributors().getFirst().championRoleKey());if(cc.contributors().size()>1)supporting.add(cc.contributors().get(1).championRoleKey());}boolean distinct=d.contributorRequirement()==ContributorRequirement.ANY||!primary(coverage,d.distinctCapabilities().get(0)).equals(primary(coverage,d.distinctCapabilities().get(1)));double factor=switch(d.contributorRequirement()){case ANY->1.0;case DISTINCT_PREFERRED->distinct?1.0:.70;case DISTINCT_REQUIRED->distinct?1.0:0.0;};double base=product==0?0.0:Math.cbrt(product),ready=zero(Math.max(0,Math.min(1,base*factor)));return new PatternEvaluation(d.pattern(),zero(base),factor,ready,d.contributorRequirement(),distinct,components,primary,supporting);}private ChampionRoleKey primary(TeamCompositionCoverage c,CompositionCapability x){return c.capability(x).contributors().getFirst().championRoleKey();}private static double zero(double v){return v==0?0.0:v;}}
